// The API reference is generated by starlight-openapi, whose labels are in
// English with no way to translate them (HiDeoo/starlight-openapi#132). On a
// French page, a passage in another language must say so (RGAA 8.7): every
// one of these labels in the text of a page is wrapped in <span lang="en">,
// and an element whose English is in an attribute or written by a script
// gets lang="en".

/** The starlight-openapi version `ENGLISH_LABELS` was read from. */
export const LABELS_VERSION = '0.27.0';

/** The title starlight-openapi gives its overview pages: routeData.ts replaces it. */
export const OVERVIEW = 'Overview';

/** The other English labels starlight-openapi writes into a page. */
const ENGLISH_LABELS = [
  'Any of',
  'Authentication',
  'Authorizations',
  'Callbacks',
  'Code sample',
  'Contact',
  'Cookie Parameters',
  'deprecated',
  'Example',
  'Examples',
  'Header Parameters',
  'Headers',
  'Media type',
  'One of',
  'Operations',
  'Parameters',
  'Path Parameters',
  'Query Parameters',
  'Request Body',
  'required',
  'Responses',
  'Select code sample',
  'Terms of Service',
  'Webhooks',
];

/**
 * The opening tag of an element whose English is not in the text: the
 * operation URLs button names itself in aria-label, and the code sample
 * picker announces « Showing Fetch code sample. » in a live region.
 */
const ENGLISH_ELEMENTS =
  /<(?:button\s[^>]*aria-label="Toggle operation URLs"|div\s[^>]*id="sl-openapi-snippet-status")[^>]*>/g;

/** A lang="en" attribute. */
const LANG_EN = /\slang="en"/;

/** A label, the longest first so that « Query Parameters » wins over « Parameters ». */
const LABEL = new RegExp(
  `\\b(?:${[...ENGLISH_LABELS].sort((a, b) => b.length - a.length).join('|')})\\b`,
  'g',
);

/**
 * An element whose content cannot hold a <span> or is data (code blocks,
 * scripts, styles, the page title), or the text between two tags.
 */
const TEXT = /(<(pre|script|style|title)\b[\s\S]*?<\/\2>)|>([^<]+)(?=<)/g;

/** A label already marked. */
const MARKED = /<span lang="en">[^<]*<\/span>/g;

/**
 * Wraps every English label of a page's text in <span lang="en"> and gives
 * lang="en" to the elements whose English is not in the text.
 */
export function markEnglishLabels(html: string): string {
  return html
    .replace(TEXT, (match: string, ...groups: (string | undefined)[]) => {
      const [skipped, , text = ''] = groups;
      if (skipped) return match;
      return `>${text.replace(LABEL, (label) => `<span lang="en">${label}</span>`)}`;
    })
    .replace(ENGLISH_ELEMENTS, (tag) =>
      LANG_EN.test(tag) ? tag : tag.replace(/^<\w+/, (name) => `${name} lang="en"`),
    );
}

/**
 * The English labels of a page's text that are not wrapped in
 * <span lang="en">, and the elements whose English is not in the text that
 * lack lang="en".
 */
export function unmarkedEnglishLabels(html: string): string[] {
  const labels = Array.from(html.replace(MARKED, '').matchAll(TEXT)).flatMap(
    ([, skipped, , text = '']) => (skipped ? [] : (text.match(LABEL) ?? [])),
  );
  const elements = (html.match(ENGLISH_ELEMENTS) ?? []).filter((tag) => !LANG_EN.test(tag));
  return [...labels, ...elements];
}
